-- "Which of my characters has it?" for the ndGUI item containers (ndgui-inventory, generated by
-- tools/fork_windows.py, which wires this module in).
--
-- Every container window you open (inventory, backpacks, bank) saves what it holds for the current
-- character in ndgui-inventory's ui.storage, which every character on this machine shares. Typing in
-- a container's search box then also looks through everything saved for your other characters and
-- other containers, and a gold "Alts: N" beside the box lists where (hover it).
--
-- Storage: "inv:<who>:<box>" = title, chunk count, saved time; "inv:<who>:<box>:<n>" = items
-- (name RS ql RS count, US-separated, chunks under 3.9 kB); "who:<who>" = character name;
-- "invidx" = every "<who>:<box>"; "invrev" changes on every save so other windows re-read.
-- Loot / corpse / chest windows are not saved. Two backpacks with the same name share one entry.
local A = {}

local US, RS = string.char(31), string.char(30)
local CHUNK = 3900
local SKIP = { "loot", "corpse", "remains", "chest" }
local MAX_TIP = 24

local function read(key)
	local ok, value = pcall(ui.storage.read, key)
	return ok and type(value) == "string" and value or ""
end

local function write(key, value)
	return (pcall(ui.storage.write, key, value))
end

local function hash(text)
	local h1, h2 = 5381, 52711
	for i = 1, #text do
		local c = text:byte(i)
		h1 = (h1 * 33 + c) % 4294967296
		h2 = (h2 * 31 + c) % 4294967296
	end
	return string.format("%08x%08x", h1, h2)
end
A.hash = hash

local function clean(text)
	return (tostring(text or ""):gsub("[" .. US .. RS .. "]", " "))
end

local me = {}
local pending -- a container seen before we knew who we are
local hits_view
local saved_text = {}
local cache = { rev = nil, boxes = {} }

-- items -> chunks of "name RS ql RS count" joined by US (sorted, merged by name + QL)
function A.encode(snapshot)
	local merged, order = {}, {}
	for _, entry in ipairs(snapshot or {}) do
		if entry.occupied and entry.name and entry.name ~= "" then
			local key = clean(entry.name) .. RS .. tostring(entry.quality or 0)
			if not merged[key] then
				merged[key] = 0
				order[#order + 1] = key
			end
			merged[key] = merged[key] + math.max(1, entry.count or 1)
		end
	end
	table.sort(order)
	local chunks, current = {}, {}
	local size = 0
	for _, key in ipairs(order) do
		local item = key .. RS .. merged[key]
		if size + #item + 1 > CHUNK and #current > 0 then
			chunks[#chunks + 1] = table.concat(current, US)
			current, size = {}, 0
		end
		current[#current + 1] = item
		size = size + #item + 1
	end
	if #current > 0 then
		chunks[#chunks + 1] = table.concat(current, US)
	end
	return chunks
end

function A.decode(chunk)
	local items = {}
	for item in (chunk or ""):gmatch("[^" .. US .. "]+") do
		local name, ql, count = item:match("^(.-)" .. RS .. "(%d+)" .. RS .. "(%d+)$")
		if name then
			items[#items + 1] = { name = name, ql = tonumber(ql), count = tonumber(count) }
		end
	end
	return items
end

function A.skipped(title)
	local lower = string.lower(title or "")
	if lower == "" then
		return true
	end
	for _, word in ipairs(SKIP) do
		if lower:find(word, 1, true) then
			return true
		end
	end
	return false
end

-- containers every character of the account sees (the account bank)
function A.shared(title)
	return string.lower(title or ""):find("account", 1, true) ~= nil
end

local function index_add(entry)
	local index = read("invidx")
	for item in index:gmatch("[^,]+") do
		if item == entry then
			return
		end
	end
	write("invidx", index == "" and entry or (index .. "," .. entry))
end

function A.record(title, snapshot)
	if A.skipped(title) then
		return
	end
	if not me.id then
		pending = { title, snapshot }
		return
	end
	local box = hash(title)
	local base = "inv:" .. me.id .. ":" .. box
	local chunks = A.encode(snapshot)
	local text = table.concat(chunks, "|")
	if saved_text[base] == text then
		return
	end
	saved_text[base] = text
	local old = tonumber((read(base):match(US .. "(%d+)" .. US)) or "0") or 0
	for n, chunk in ipairs(chunks) do
		write(base .. ":" .. n, chunk)
	end
	for n = #chunks + 1, old do
		write(base .. ":" .. n, "")
	end
	local ok, now = pcall(ui.time)
	write(base, clean(title) .. US .. #chunks .. US .. tostring(ok and math.floor(now) or 0))
	write("who:" .. me.id, clean(me.name))
	index_add(me.id .. ":" .. box)
	write("invrev", tostring((tonumber(read("invrev")) or 0) + 1))
end

local function boxes()
	local rev = read("invrev")
	if cache.rev == rev then
		return cache.boxes
	end
	cache.rev, cache.boxes = rev, {}
	for entry in read("invidx"):gmatch("[^,]+") do
		local who, box = entry:match("^(.-):(.+)$")
		local base = "inv:" .. entry
		local title, count, saved = read(base):match("^(.-)" .. US .. "(%d+)" .. US .. "(%d*)")
		if who and title then
			local items = {}
			for n = 1, tonumber(count) do
				for _, item in ipairs(A.decode(read(base .. ":" .. n))) do
					item.lower = string.lower(item.name)
					items[#items + 1] = item
				end
			end
			local box = { who = who, name = read("who:" .. who), title = title, items = items, saved = tonumber(saved) or 0,
				shared = A.shared(title) }
			cache.boxes[#cache.boxes + 1] = box
		end
	end
	-- a shared container (the account bank) counts once: the copy saved last, whoever opened it
	local newest = {}
	for _, box in ipairs(cache.boxes) do
		if box.shared and (not newest[box.title] or box.saved > newest[box.title].saved) then
			newest[box.title] = box
		end
	end
	local kept = {}
	for _, box in ipairs(cache.boxes) do
		if not box.shared or newest[box.title] == box then
			kept[#kept + 1] = box
		end
	end
	cache.boxes = kept
	return cache.boxes
end

-- matches for `query` everywhere except `here_title` of the current character
function A.find(query, here_title)
	local q = string.lower((query or ""):gsub("^%s+", ""):gsub("%s+$", ""))
	local found = {}
	if #q < 3 then
		return found
	end
	for _, box in ipairs(boxes()) do
		local here = box.title == here_title and (box.who == me.id or box.shared)
		if not here then
			for _, item in ipairs(box.items) do
				if item.lower:find(q, 1, true) then
					found[#found + 1] = { who = box.shared and "" or box.who, name = box.name ~= "" and box.name or "?", title = box.title,
						item = item, mine = box.who == me.id and not box.shared, shared = box.shared }
				end
			end
		end
	end
	table.sort(found, function(a, b)
		if a.mine ~= b.mine then return a.mine end
		if a.name ~= b.name then return a.name < b.name end
		return a.item.name < b.item.name
	end)
	return found
end

local here_title = ""

function A.title(title)
	here_title = title or ""
end

function A.search(value)
	if not hits_view then
		return
	end
	local found = A.find(value, here_title)
	ui.visible(hits_view, #found > 0)
	if #found == 0 then
		return
	end
	local places = {}
	local lines = {}
	for index, hit in ipairs(found) do
		places[hit.who .. hit.title] = true
		if index <= MAX_TIP then
			local where = hit.shared and hit.title or ((hit.mine and "You" or hit.name) .. " - " .. hit.title)
			lines[#lines + 1] = string.format("%s: %s (QL %d)%s", where, hit.item.name,
				hit.item.ql or 0, (hit.item.count or 1) > 1 and (" x" .. hit.item.count) or "")
		end
	end
	if #found > MAX_TIP then
		lines[#lines + 1] = string.format("... and %d more", #found - MAX_TIP)
	end
	local n = 0
	for _ in pairs(places) do n = n + 1 end
	ui.text(hits_view, "+" .. n)
	ui.tooltip(hits_view, "Also in " .. n .. (n == 1 and " other place" or " other places") .. " (as saved when that container was last open):" .. string.char(10) .. table.concat(lines, string.char(10)))
end

function A.mount(content)
	local ok, view = pcall(ui.find, content, "ndgui_alt_hits")
	hits_view = ok and view or nil
	if hits_view then
		ui.visible(hits_view, false)
	end
	pcall(game.character.subscribe, "self", "", function(_, character)
		if not character then
			return
		end
		local key = character.key or (character.name and ("name:" .. character.name))
		if key then
			me.id, me.name = hash(key), character.name or me.name
			if pending then
				local p = pending
				pending = nil
				A.record(p[1], p[2])
			end
		end
	end)
end

function A.me(id, name) -- tests
	me.id, me.name = id, name
end

return A
